class Solution:
    def combine(self, n: int, k: int) -> List[List[int]]:
        cur_comb = []
        ans = []

        def choose(start: int) -> None:
            if len(cur_comb) == k:
                ans.append(cur_comb[:])
                return

            for i in range(start, n + 1):
                cur_comb.append(i)
                choose(i + 1)
                cur_comb.pop()

        choose(1)
        return ans
